"""Rounded water-cell corners, continuous heading/turns and a complete voyage."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_bytes();sha=hashlib.sha256(source).hexdigest()
script=source.decode().replace('// SOURCE: 99-instrumentation.js',r'''
window.__waterMotion=()=>{const options={...gameOptions},oldClock=frameClock,oldCam={...cam};try{Object.assign(gameOptions,{quality:'high',effects:true,traffic:true,reducedMotion:false});cam.zoom=1;const path=[roadId(1,10),roadId(2,10),roadId(2,11)],positions=[];for(let t=0;t<=2;t+=.01){const p=waterRoutePose(path,t);if(!waterNetwork().nodes.has(Math.floor(p.gy)*T+Math.floor(p.gx)))throw Error('Rounded turn left navigable water');positions.push(p);}const a=waterRoutePose(path,.999),b=waterRoutePose(path,1.001),cornerAngle=Math.abs(Math.atan2(a.dy,a.dx)-Math.atan2(b.dy,b.dx)),coarseA=waterRoutePose(path,.99),coarseB=waterRoutePose(path,1.01),coarseAngle=Math.abs(Math.atan2(coarseA.dy,coarseA.dx)-Math.atan2(coarseB.dy,coarseB.dx));let last=null,maxStep=0,maxAngle=0,turnFrames=0,id=null,finished=false;for(let i=0;i<1300;i++){frameClock+=.1;const boat=waterfrontActors(()=>true).find(a=>a.cargo!=='fish');if(!boat)continue;if(id==null)id=boat.id;if(boat.id!==id)throw Error('Vessel identity changed during voyage');if(last){maxStep=Math.max(maxStep,Math.hypot(boat.x-last.x,boat.y-last.y));const delta=Math.atan2(boat.dy,boat.dx)-Math.atan2(last.dy,last.dx);maxAngle=Math.max(maxAngle,Math.abs(Math.atan2(Math.sin(delta),Math.cos(delta))));}if(boat.turnRemaining>0)turnFrames++;if(!boat.active)finished=true;last={x:boat.x,y:boat.y,dx:boat.dx,dy:boat.dy};}return {samples:positions.length,cornerAngle,coarseAngle,maxStep,maxAngle,turnFrames,finished};}finally{Object.assign(gameOptions,options);frameClock=oldClock;cam=oldCam;dirty=true;}};
// SOURCE: 99-instrumentation.js''')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390});p.set_content(html);p.add_script_tag(content=script);p.locator('#newTown').click();p.locator('#pause').click();p.evaluate('__townTest.reset("settlement",42)');p.evaluate('__townTest.step(5)');raw=p.evaluate('__townTest.save()');r=p.evaluate('__waterMotion()');assert r['cornerAngle']<.03 and r['cornerAngle']<r['coarseAngle']*.11 and r['maxStep']<3 and r['maxAngle']<.3 and r['turnFrames']>=10 and r['finished'],r;assert p.evaluate('__townTest.save()')==raw;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-survey-play';out.mkdir(exist_ok=True);(out/'water-motion.json').write_text(json.dumps({'source_sha256':sha,**r},indent=2)+'\n');print('PASS rounded navigable corners, bounded per-frame movement/heading, turn dwell, full outward/return voyage and unchanged economic archive',r)
